INSERT INTO Feat (featName, featSlug, featCategory, featPrereq, featMinLevel, featRepeatable, featDescription, sourceID) VALUES ('Alert', 'alert', 'origin', NULL, NULL, 0, 'You gain the following benefits.
**Initiative Proficiency.** When you roll Initiative, you can add your Proficiency Bonus to the roll.
**Initiative Swap.** Immediately after you roll Initiative, you can swap your Initiative with the Initiative of one willing ally in the same combat. You can''t make this swap if you or the ally has the Incapacitated condition.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
  ON CONFLICT (featSlug) DO UPDATE SET featName = excluded.featName, featCategory = excluded.featCategory, featPrereq = excluded.featPrereq, featMinLevel = excluded.featMinLevel, featRepeatable = excluded.featRepeatable, featDescription = excluded.featDescription, sourceID = excluded.sourceID;
INSERT INTO Feat (featName, featSlug, featCategory, featPrereq, featMinLevel, featRepeatable, featDescription, sourceID) VALUES ('Magic Initiate', 'magic-initiate', 'origin', NULL, NULL, 1, 'You gain the following benefits.
**Two Cantrips.** You learn two cantrips of your choice from the Cleric, Druid, or Wizard spell list. Intelligence, Wisdom, or Charisma is your spellcasting ability for this feat''s spells (choose when you select this feat).
**Level 1 Spell.** Choose a level 1 spell from the same list you selected for this feat''s cantrips. You always have that spell prepared. You can cast it once without a spell slot, and you regain the ability to cast it in that way when you finish a Long Rest. You can also cast the spell using any spell slots you have.
**Spell Change.** Whenever you gain a new level, you can replace one of the spells you chose for this feat with a different spell of the same level from the chosen spell list.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
  ON CONFLICT (featSlug) DO UPDATE SET featName = excluded.featName, featCategory = excluded.featCategory, featPrereq = excluded.featPrereq, featMinLevel = excluded.featMinLevel, featRepeatable = excluded.featRepeatable, featDescription = excluded.featDescription, sourceID = excluded.sourceID;
INSERT INTO Feat (featName, featSlug, featCategory, featPrereq, featMinLevel, featRepeatable, featDescription, sourceID) VALUES ('Savage Attacker', 'savage-attacker', 'origin', NULL, NULL, 0, 'You''ve trained to deal particularly damaging strikes. Once per turn when you hit a target with a weapon, you can roll the weapon''s damage dice twice and use either roll against the target.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
  ON CONFLICT (featSlug) DO UPDATE SET featName = excluded.featName, featCategory = excluded.featCategory, featPrereq = excluded.featPrereq, featMinLevel = excluded.featMinLevel, featRepeatable = excluded.featRepeatable, featDescription = excluded.featDescription, sourceID = excluded.sourceID;
INSERT INTO Feat (featName, featSlug, featCategory, featPrereq, featMinLevel, featRepeatable, featDescription, sourceID) VALUES ('Skilled', 'skilled', 'origin', NULL, NULL, 1, 'You gain proficiency in any combination of three skills or tools of your choice.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
  ON CONFLICT (featSlug) DO UPDATE SET featName = excluded.featName, featCategory = excluded.featCategory, featPrereq = excluded.featPrereq, featMinLevel = excluded.featMinLevel, featRepeatable = excluded.featRepeatable, featDescription = excluded.featDescription, sourceID = excluded.sourceID;
INSERT INTO Feat (featName, featSlug, featCategory, featPrereq, featMinLevel, featRepeatable, featDescription, sourceID) VALUES ('Ability Score Improvement', 'ability-score-improvement', 'general', 'Level 4+', 4, 1, 'Increase one ability score of your choice by 2, or increase two ability scores of your choice by 1. This feat can''t increase an ability score above 20.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
  ON CONFLICT (featSlug) DO UPDATE SET featName = excluded.featName, featCategory = excluded.featCategory, featPrereq = excluded.featPrereq, featMinLevel = excluded.featMinLevel, featRepeatable = excluded.featRepeatable, featDescription = excluded.featDescription, sourceID = excluded.sourceID;
INSERT INTO Feat (featName, featSlug, featCategory, featPrereq, featMinLevel, featRepeatable, featDescription, sourceID) VALUES ('Grappler', 'grappler', 'general', 'Level 4+, Strength or Dexterity 13+', 4, 0, 'You gain the following benefits.
**Ability Score Increase.** Increase your Strength or Dexterity score by 1, to a maximum of 20.
**Punch and Grab.** When you hit a creature with an Unarmed Strike as part of the Attack action on your turn, you can use both the Damage and the Grapple option. You can use this benefit only once per turn.
**Attack Advantage.** You have Advantage on attack rolls against a creature Grappled by you.
**Fast Wrestler.** You don''t have to spend extra movement to move a creature Grappled by you if the creature is your size or smaller.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
  ON CONFLICT (featSlug) DO UPDATE SET featName = excluded.featName, featCategory = excluded.featCategory, featPrereq = excluded.featPrereq, featMinLevel = excluded.featMinLevel, featRepeatable = excluded.featRepeatable, featDescription = excluded.featDescription, sourceID = excluded.sourceID;
INSERT INTO Feat (featName, featSlug, featCategory, featPrereq, featMinLevel, featRepeatable, featDescription, sourceID) VALUES ('Archery', 'archery', 'fighting_style', NULL, NULL, 0, 'You gain a +2 bonus to attack rolls you make with Ranged weapons.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
  ON CONFLICT (featSlug) DO UPDATE SET featName = excluded.featName, featCategory = excluded.featCategory, featPrereq = excluded.featPrereq, featMinLevel = excluded.featMinLevel, featRepeatable = excluded.featRepeatable, featDescription = excluded.featDescription, sourceID = excluded.sourceID;
INSERT INTO Feat (featName, featSlug, featCategory, featPrereq, featMinLevel, featRepeatable, featDescription, sourceID) VALUES ('Defense', 'defense', 'fighting_style', NULL, NULL, 0, 'While you''re wearing Light, Medium, or Heavy armor, you gain a +1 bonus to Armor Class.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
  ON CONFLICT (featSlug) DO UPDATE SET featName = excluded.featName, featCategory = excluded.featCategory, featPrereq = excluded.featPrereq, featMinLevel = excluded.featMinLevel, featRepeatable = excluded.featRepeatable, featDescription = excluded.featDescription, sourceID = excluded.sourceID;
INSERT INTO Feat (featName, featSlug, featCategory, featPrereq, featMinLevel, featRepeatable, featDescription, sourceID) VALUES ('Great Weapon Fighting', 'great-weapon-fighting', 'fighting_style', NULL, NULL, 0, 'When you roll damage for an attack you make with a Melee weapon that you are holding with two hands, you can treat any 1 or 2 on a damage die as a 3. The weapon must have the Two-Handed or Versatile property to gain this benefit.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
  ON CONFLICT (featSlug) DO UPDATE SET featName = excluded.featName, featCategory = excluded.featCategory, featPrereq = excluded.featPrereq, featMinLevel = excluded.featMinLevel, featRepeatable = excluded.featRepeatable, featDescription = excluded.featDescription, sourceID = excluded.sourceID;
INSERT INTO Feat (featName, featSlug, featCategory, featPrereq, featMinLevel, featRepeatable, featDescription, sourceID) VALUES ('Two Weapon Fighting', 'two-weapon-fighting', 'fighting_style', NULL, NULL, 0, 'When you make an extra attack as a result of using a weapon that has the Light property, you can add your ability modifier to the damage of that attack if you aren''t already adding it to the damage.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
  ON CONFLICT (featSlug) DO UPDATE SET featName = excluded.featName, featCategory = excluded.featCategory, featPrereq = excluded.featPrereq, featMinLevel = excluded.featMinLevel, featRepeatable = excluded.featRepeatable, featDescription = excluded.featDescription, sourceID = excluded.sourceID;
INSERT INTO Feat (featName, featSlug, featCategory, featPrereq, featMinLevel, featRepeatable, featDescription, sourceID) VALUES ('Boon of Combat Prowess', 'boon-of-combat-prowess', 'epic_boon', 'Level 19+', 19, 0, 'You gain the following benefits.
**Ability Score Increase.** Increase one ability score of your choice by 1, to a maximum of 30.
**Peerless Aim.** When you miss with an attack roll, you can hit instead. Once you use this benefit, you can''t use it again until the start of your next turn.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
  ON CONFLICT (featSlug) DO UPDATE SET featName = excluded.featName, featCategory = excluded.featCategory, featPrereq = excluded.featPrereq, featMinLevel = excluded.featMinLevel, featRepeatable = excluded.featRepeatable, featDescription = excluded.featDescription, sourceID = excluded.sourceID;
INSERT INTO Feat (featName, featSlug, featCategory, featPrereq, featMinLevel, featRepeatable, featDescription, sourceID) VALUES ('Boon of Dimensional Travel', 'boon-of-dimensional-travel', 'epic_boon', 'Level 19+', 19, 0, 'You gain the following benefits.
**Ability Score Increase.** Increase one ability score of your choice by 1, to a maximum of 30.
**Blink Steps.** Immediately after you take the Attack action or the Magic action, you can teleport up to 30 feet to an unoccupied space you can see.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
  ON CONFLICT (featSlug) DO UPDATE SET featName = excluded.featName, featCategory = excluded.featCategory, featPrereq = excluded.featPrereq, featMinLevel = excluded.featMinLevel, featRepeatable = excluded.featRepeatable, featDescription = excluded.featDescription, sourceID = excluded.sourceID;
INSERT INTO Feat (featName, featSlug, featCategory, featPrereq, featMinLevel, featRepeatable, featDescription, sourceID) VALUES ('Boon of Fate', 'boon-of-fate', 'epic_boon', 'Level 19+', 19, 0, 'You gain the following benefits.
**Ability Score Increase.** Increase one ability score of your choice by 1, to a maximum of 30.
**Improve Fate.** When you or another creature within 60 feet of you succeeds on or fails a D20 Test, you can roll 2d4 and apply the total rolled as a bonus or penalty to the d20 roll. Once you use this benefit, you can''t use it again until you roll Initiative or finish a Short or Long Rest.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
  ON CONFLICT (featSlug) DO UPDATE SET featName = excluded.featName, featCategory = excluded.featCategory, featPrereq = excluded.featPrereq, featMinLevel = excluded.featMinLevel, featRepeatable = excluded.featRepeatable, featDescription = excluded.featDescription, sourceID = excluded.sourceID;
INSERT INTO Feat (featName, featSlug, featCategory, featPrereq, featMinLevel, featRepeatable, featDescription, sourceID) VALUES ('Boon of Irresistible Offense', 'boon-of-irresistible-offense', 'epic_boon', 'Level 19+', 19, 0, 'You gain the following benefits.
**Ability Score Increase.** Increase one ability score of your choice by 1, to a maximum of 30.
**Overcome Defenses.** The Bludgeoning, Piercing, and Slashing damage you deal always ignores Resistance.
**Overwhelming Strike.** When you roll a 20 on the d20 for an attack roll, you can deal extra damage to the target equal to the ability score increased by this feat. The extra damage''s type is the same as the attack''s type.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
  ON CONFLICT (featSlug) DO UPDATE SET featName = excluded.featName, featCategory = excluded.featCategory, featPrereq = excluded.featPrereq, featMinLevel = excluded.featMinLevel, featRepeatable = excluded.featRepeatable, featDescription = excluded.featDescription, sourceID = excluded.sourceID;
INSERT INTO Feat (featName, featSlug, featCategory, featPrereq, featMinLevel, featRepeatable, featDescription, sourceID) VALUES ('Boon of Spell Recall', 'boon-of-spell-recall', 'epic_boon', 'Level 19+', 19, 0, 'You gain the following benefits.
**Ability Score Increase.** Increase one ability score of your choice by 1, to a maximum of 30.
**Free Casting.** Whenever you cast a spell with a level 1–4 spell slot, roll 1d4. If the number you roll is the same as the slot''s level, the slot isn''t expended.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
  ON CONFLICT (featSlug) DO UPDATE SET featName = excluded.featName, featCategory = excluded.featCategory, featPrereq = excluded.featPrereq, featMinLevel = excluded.featMinLevel, featRepeatable = excluded.featRepeatable, featDescription = excluded.featDescription, sourceID = excluded.sourceID;
INSERT INTO Feat (featName, featSlug, featCategory, featPrereq, featMinLevel, featRepeatable, featDescription, sourceID) VALUES ('Boon of the Night Spirit', 'boon-of-the-night-spirit', 'epic_boon', 'Level 19+', 19, 0, 'You gain the following benefits.
**Ability Score Increase.** Increase one ability score of your choice by 1, to a maximum of 30.
**Merge with Shadows.** While within Dim Light or Darkness, you can give yourself the Invisible condition as a Bonus Action. The condition ends on you immediately after you take an action, a Bonus Action, or a Reaction.
**Shadowy form.** While within Dim Light or Darkness, you have Resistance to all damage except Psychic and Radiant.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
  ON CONFLICT (featSlug) DO UPDATE SET featName = excluded.featName, featCategory = excluded.featCategory, featPrereq = excluded.featPrereq, featMinLevel = excluded.featMinLevel, featRepeatable = excluded.featRepeatable, featDescription = excluded.featDescription, sourceID = excluded.sourceID;
INSERT INTO Feat (featName, featSlug, featCategory, featPrereq, featMinLevel, featRepeatable, featDescription, sourceID) VALUES ('Boon of Truesight', 'boon-of-truesight', 'epic_boon', 'Level 19+', 19, 0, 'You gain the following benefits.
**Ability Score Increase.** Increase one ability score of your choice by 1, to a maximum of 30.
**Truesight.** You have Truesight with a range of 60 feet.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
  ON CONFLICT (featSlug) DO UPDATE SET featName = excluded.featName, featCategory = excluded.featCategory, featPrereq = excluded.featPrereq, featMinLevel = excluded.featMinLevel, featRepeatable = excluded.featRepeatable, featDescription = excluded.featDescription, sourceID = excluded.sourceID;
