INSERT INTO SpeciesTrait (speciesID, speciesTraitName, speciesTraitDescription, sortOrder) VALUES ((SELECT speciesID FROM Species WHERE speciesSlug = 'orc'), 'Adrenaline Rush', 'You can take the Dash action as a Bonus Action. When you do so, you gain a number of Temporary Hit Points equal to your Proficiency Bonus.
You can use this trait a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Short or Long Rest.', 1);
INSERT INTO SpeciesTrait (speciesID, speciesTraitName, speciesTraitDescription, sortOrder) VALUES ((SELECT speciesID FROM Species WHERE speciesSlug = 'halfling'), 'Brave', 'You have Advantage on saving throws you make to avoid or end the Frightened condition.', 2);
INSERT INTO SpeciesTrait (speciesID, speciesTraitName, speciesTraitDescription, sortOrder) VALUES ((SELECT speciesID FROM Species WHERE speciesSlug = 'dragonborn'), 'Damage Resistance: Lightning', 'You have Resistance to lightning damage, as determined by your Draconic Ancestry trait.', 11);
INSERT INTO SpeciesTrait (speciesID, speciesTraitName, speciesTraitDescription, sortOrder) VALUES ((SELECT speciesID FROM Species WHERE speciesSlug = 'dragonborn'), 'Damage Resistance: Poison', 'You have Resistance to poison damage, as determined by your Draconic Ancestry trait.', 12);
INSERT INTO SpeciesTrait (speciesID, speciesTraitName, speciesTraitDescription, sortOrder) VALUES ((SELECT speciesID FROM Species WHERE speciesSlug = 'dragonborn'), 'Darkvision (60 ft.)', 'You have Darkvision with a range of 60 feet.', 13);
INSERT INTO SpeciesTrait (speciesID, speciesTraitName, speciesTraitDescription, sortOrder) VALUES ((SELECT speciesID FROM Species WHERE speciesSlug = 'elf'), 'Darkvision (60 ft.)', 'You have Darkvision with a range of 60 feet.', 13);
INSERT INTO SpeciesTrait (speciesID, speciesTraitName, speciesTraitDescription, sortOrder) VALUES ((SELECT speciesID FROM Species WHERE speciesSlug = 'gnome'), 'Darkvision (60 ft.)', 'You have Darkvision with a range of 60 feet.', 13);
INSERT INTO SpeciesTrait (speciesID, speciesTraitName, speciesTraitDescription, sortOrder) VALUES ((SELECT speciesID FROM Species WHERE speciesSlug = 'tiefling'), 'Darkvision (60 ft.)', 'You have Darkvision with a range of 60 feet.', 13);
INSERT INTO SpeciesTrait (speciesID, speciesTraitName, speciesTraitDescription, sortOrder) VALUES ((SELECT speciesID FROM Species WHERE speciesSlug = 'dragonborn'), 'Draconic Ancestry', 'Your lineage stems from a dragon progenitor. Choose the kind of dragon from the Draconic Ancestors table. Your choice affects your Breath Weapon and Damage Resistance traits as well as your appearance.
Draconic Ancestors
Dragon / Damage Type
Black / Acid
Blue / Lightning
Brass / Fire
Bronze / Lightning
Copper / Acid
Green / Poison
Gold / Fire
Red / Fire
Silver / Cold
White / Cold', 15);
INSERT INTO SpeciesTrait (speciesID, speciesTraitName, speciesTraitDescription, sortOrder) VALUES ((SELECT speciesID FROM Species WHERE speciesSlug = 'dragonborn'), 'Draconic Flight', 'When you reach character level 5, you can channel draconic magic to give yourself temporary flight. As a Bonus Action, you sprout spectral wings on your back that last for 10 minutes or until you retract the wings (no action required) or have the Incapacitated condition. During that time, you have a Fly Speed equal to your Speed. Your wings appear to be made of the same energy as your Breath Weapon. Once you use this trait, you can''t use it again until you finish a Long Rest.', 16);
INSERT INTO SpeciesTrait (speciesID, speciesTraitName, speciesTraitDescription, sortOrder) VALUES ((SELECT speciesID FROM Species WHERE speciesSlug = 'dwarf'), 'Dwarven Resilience', 'You have Resistance to Poison damage. You also have Advantage on saving throws you make to avoid or end the Poisoned condition.', 17);
INSERT INTO SpeciesTrait (speciesID, speciesTraitName, speciesTraitDescription, sortOrder) VALUES ((SELECT speciesID FROM Species WHERE speciesSlug = 'dwarf'), 'Dwarven Toughness', 'Your Hit Point maximum increases by 1, and it increases by 1 again whenever you gain a level.', 18);
INSERT INTO SpeciesTrait (speciesID, speciesTraitName, speciesTraitDescription, sortOrder) VALUES ((SELECT speciesID FROM Species WHERE speciesSlug = 'elf'), 'Elven Lineage', 'You are part of a lineage that grants you supernatural abilities. Choose a lineage from the Elven Lineages table. You gain the level 1 benefit of that lineage.
When you reach character levels 3 and 5, you learn a higher-level spell, as shown on the table.
You always have that spell prepared. You can cast it once without a spell slot, and you regain the ability to cast it in that way when you finish a Long Rest. You can also cast the spell using any spell slots you have of the appropriate level.
Elven Lineages
Drow
Level 1. The range of your Darkvision increases to 120 feet. You also know the Dancing Lights cantrip.
Level 3. Faerie Fire
Level 5. Darkness
High Elf
Level 1. You know the Prestidigitation cantrip. Whenever you finish a Long Rest, you can replace that cantrip with a different cantrip from the Wizard spell list.
Level 3. Detect Magic
Level 5. Misty Step
Wood Elf
Level 1. Your Speed increases to 35 feet. You also know the Druidcraft cantrip.
Level 3. Longstrider
Level 5. Pass without Trace
Intelligence, Wisdom, or Charisma is your spellcasting ability for the spells you cast with this trait (choose the ability when you select the lineage).', 19);
INSERT INTO SpeciesTrait (speciesID, speciesTraitName, speciesTraitDescription, sortOrder) VALUES ((SELECT speciesID FROM Species WHERE speciesSlug = 'elf'), 'Fey Ancestry', 'You have Advantage on saving throws you make to avoid or end the Charmed condition.', 20);
INSERT INTO SpeciesTrait (speciesID, speciesTraitName, speciesTraitDescription, sortOrder) VALUES ((SELECT speciesID FROM Species WHERE speciesSlug = 'tiefling'), 'Fiendish Legacy', 'You are the recipient of a legacy that grants you supernatural abilities. Choose a legacy from the Fiendish Legacies table. You gain the level 1 benefit of the chosen legacy.
When you reach character levels 3 and 5, you learn a higher-level spell, as shown on the table.
You always have that spell prepared. You can cast it once without a spell slot, and you regain the ability to cast it in that way when you finish a Long Rest. You can also cast the spell using any spell slots you have of the appropriate level.
Intelligence, Wisdom, or Charisma is your spell-casting ability for the spells you cast with this trait (choose the ability when you select the legacy).
Fiendish Legacies
Abyssal.
Level 1. You have Resistance to Poison damage. You also know the Poison Spray cantrip.
Level 3. Ray of Sickness
Level 5. Hold Person
Chthonic.
Level 1. You have Resistance to Necrotic damage. You also know the Chill Touch cantrip.
Level 3. False Life
Level 5. Ray of Enfeeblement
Infernal.
Level 1. You have Resistance to Fire damage. You also know the Fire Bolt cantrip.
Level 3. Hellish Rebuke
Level 5. Darkness', 21);
INSERT INTO SpeciesTrait (speciesID, speciesTraitName, speciesTraitDescription, sortOrder) VALUES ((SELECT speciesID FROM Species WHERE speciesSlug = 'goliath'), 'Giant Ancestry', 'You are descended from Giants. Choose one of the following benefits-a supernatural boon from your ancestry; you can use the chosen benefit a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest:
Cloud''s Jaunt (Cloud Giant). As a Bonus Action, you magically teleport up to 30 feet to an unoccupied space you can see.
Fire''s Burn (Fire Giant). When you hit a target with an attack roll and deal damage to it, you can also deal 1d10 Fire damage to that target.
Frost''s Chill (Frost Giant). When you hit a target with an attack roll and deal damage to it, you can also deal 1d6 Cold damage to that target and reduce its Speed by 10 feet until the start of your next turn.
Hill''s Tumble (Hill Giant). When you hit a Large or smaller creature with an attack roll and deal damage to it, you can give that target the Prone condition.
Stone''s Endurance (Stone Giant). When you take damage, you can take a Reaction to roll 1d12. Add your Constitution modifier to the number rolled and reduce the damage by that total.
- Storm''s Thunder (Storm Giant). When you take damage from a creature within 60 feet of you, you can take a Reaction to deal 1d8 Thunder damage to that creature.', 22);
INSERT INTO SpeciesTrait (speciesID, speciesTraitName, speciesTraitDescription, sortOrder) VALUES ((SELECT speciesID FROM Species WHERE speciesSlug = 'gnome'), 'Gnomish Cunning', 'You have Advantage on Intelligence, Wisdom, and Charisma saving throws.', 29);
INSERT INTO SpeciesTrait (speciesID, speciesTraitName, speciesTraitDescription, sortOrder) VALUES ((SELECT speciesID FROM Species WHERE speciesSlug = 'gnome'), 'Gnomish Lineage', 'You are part of a lineage that grants you supernatural abilities. Choose one of the following options; whichever one you choose, Intelligence, Wisdom, or Charisma is your spellcasting ability for the spells you cast with this trait (choose the ability when you select the lineage):
Forest Gnome. You know the Minor Illusion cantrip. You also always have the Speak with Animals spell prepared. You can cast it without a spell slot a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest. You can also use any spell slots you have to cast the spell.
Rock Gnome. You know the Mending and Prestidigitation cantrips. In addition, you can spend 10 minutes casting Prestidigitation to create a Tiny clockwork device (AC 5, 1 HP), such as a toy, fire starter, or music box. When you create the device, you determine its function by choosing one effect from Prestidigitation; the device produces that effect whenever you or another creature takes a Bonus Action to activate it with a touch. If the chosen effect has options within it, you choose one of those options for the device when you create it.
For example, if you choose the spell''s ignite-extinguish effect, you determine whether the device ignites or extinguishes fire; the device doesn''t do both. You can have three such devices in existence at a time, and each falls apart 8 hours after its creation or when you dismantle it with a touch as a Utilize action.', 30);
INSERT INTO SpeciesTrait (speciesID, speciesTraitName, speciesTraitDescription, sortOrder) VALUES ((SELECT speciesID FROM Species WHERE speciesSlug = 'halfling'), 'Halfling Nimbleness', 'You can move through the space of any creature that is a size larger than you, but you can''t stop in the same space.', 33);
INSERT INTO SpeciesTrait (speciesID, speciesTraitName, speciesTraitDescription, sortOrder) VALUES ((SELECT speciesID FROM Species WHERE speciesSlug = 'elf'), 'Keen Senses', 'You have proficiency in the Insight, Perception, or Survival skill.', 35);
INSERT INTO SpeciesTrait (speciesID, speciesTraitName, speciesTraitDescription, sortOrder) VALUES ((SELECT speciesID FROM Species WHERE speciesSlug = 'goliath'), 'Large Form', 'Starting at character level 5, you can change your size to Large as a Bonus Action if you''re in a big enough space. This transformation lasts for 10 minutes or until you end it (no action required). For that duration, you have Advantage on Strength checks, and your Speed increases by 10 feet. Once you use this trait, you can''t use it again until you finish a Long Rest.', 36);
INSERT INTO SpeciesTrait (speciesID, speciesTraitName, speciesTraitDescription, sortOrder) VALUES ((SELECT speciesID FROM Species WHERE speciesSlug = 'halfling'), 'Luck', 'When you roll a 1 on the d20 of a D20 Test, you can reroll the die, and you must use the new roll.', 57);
INSERT INTO SpeciesTrait (speciesID, speciesTraitName, speciesTraitDescription, sortOrder) VALUES ((SELECT speciesID FROM Species WHERE speciesSlug = 'halfling'), 'Naturally Stealthy', 'You can take the Hide action even when you are obscured only by a creature that is at least one size larger than you.', 58);
INSERT INTO SpeciesTrait (speciesID, speciesTraitName, speciesTraitDescription, sortOrder) VALUES ((SELECT speciesID FROM Species WHERE speciesSlug = 'tiefling'), 'Otherworldly Presence', 'You know the Thaumaturgy cantrip. When you cast it with this trait, the spell uses the same spellcasting ability you use for your Fiendish Legacy trait.', 59);
INSERT INTO SpeciesTrait (speciesID, speciesTraitName, speciesTraitDescription, sortOrder) VALUES ((SELECT speciesID FROM Species WHERE speciesSlug = 'goliath'), 'Powerful Build', 'You have Advantage on any ability check you make to end the Grappled condition. You also count as one size larger when determining your carrying capacity.', 60);
INSERT INTO SpeciesTrait (speciesID, speciesTraitName, speciesTraitDescription, sortOrder) VALUES ((SELECT speciesID FROM Species WHERE speciesSlug = 'orc'), 'Relentless Endurance', 'When you are reduced to 0 Hit Points but not killed outright, you can drop to 1 Hit Point instead. Once you use this trait, you can''t do so again until you finish a Long Rest.', 61);
INSERT INTO SpeciesTrait (speciesID, speciesTraitName, speciesTraitDescription, sortOrder) VALUES ((SELECT speciesID FROM Species WHERE speciesSlug = 'human'), 'Resourceful', 'You gain Heroic Inspiration whenever you finish a Long Rest.', 62);
INSERT INTO SpeciesTrait (speciesID, speciesTraitName, speciesTraitDescription, sortOrder) VALUES ((SELECT speciesID FROM Species WHERE speciesSlug = 'human'), 'Skillful', 'You gain proficiency in one skill of your choice.', 63);
INSERT INTO SpeciesTrait (speciesID, speciesTraitName, speciesTraitDescription, sortOrder) VALUES ((SELECT speciesID FROM Species WHERE speciesSlug = 'dwarf'), 'Stonecunning', 'As a Bonus Action, you gain Tremorsense with a range of 60 feet for 10 minutes. You must be on a stone surface or touching a stone surface to use this Tremorsense. The stone can be natural or worked.
You can use this Bonus Action a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest.', 64);
INSERT INTO SpeciesTrait (speciesID, speciesTraitName, speciesTraitDescription, sortOrder) VALUES ((SELECT speciesID FROM Species WHERE speciesSlug = 'elf'), 'Trance', 'You don''t need to sleep, and magic can''t put you to sleep. You can finish a Long Rest in 4 hours if you spend those hours in a trancelike meditation, during which you retain consciousness.', 65);
INSERT INTO SpeciesTrait (speciesID, speciesTraitName, speciesTraitDescription, sortOrder) VALUES ((SELECT speciesID FROM Species WHERE speciesSlug = 'human'), 'Versatile', 'You gain an Origin feat of your choice (see "Feats"). Skilled is recommended.', 66);
INSERT INTO SpeciesOption (speciesOptionSlug, speciesID, speciesOptionGroup, speciesOptionName, damageTypeID, speciesOptionDescription, speciesOptionDetails) VALUES ('draconic-ancestor-black', (SELECT speciesID FROM Species WHERE speciesSlug = 'dragonborn'), 'Draconic Ancestor', 'Black', (SELECT damageTypeID FROM DamageType WHERE damageTypeName = 'Acid' COLLATE NOCASE), 'Breath Weapon: Acid. When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in either a 15-foot Cone or a 30-foot Line that is 5 feet wide (choose the shape each time). Each creature in that area must make a Dexterity saving throw (DC 8 plus your Constitution modifier and Proficiency Bonus). On a failed save, a creature takes 1d10 acid damage. On a successful save, a creature takes half as much damage. This damage increases by 1d10 when you reach character levels 5 (2d10), 11 (3d10), and 17 (4d10).
You can use this Breath Weapon a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest.
Damage Resistance: Acid. You have Resistance to acid damage, as determined by your Draconic Ancestry trait.', '{"traits":[{"slug":"draconic-breath-weapon-acid","level":1},{"slug":"draconic-damage-resistance-acid","level":1}]}')
  ON CONFLICT (speciesOptionSlug) DO UPDATE SET speciesID = excluded.speciesID, speciesOptionGroup = excluded.speciesOptionGroup, speciesOptionName = excluded.speciesOptionName, damageTypeID = excluded.damageTypeID, speciesOptionDescription = excluded.speciesOptionDescription, speciesOptionDetails = excluded.speciesOptionDetails;
